  "description": "Python runtime and build extension for Trigger.dev",
  "license": "MIT",
  "publishConfig": {
    "access": "public"
  },
  "repository": {
    "type": "git",
    "url": "https://github.com/triggerdotdev/trigger.dev",
    "directory": "packages/python"
  },
  "type": "module",
  "files": [
    "dist"
  ],
  "tshy": {
    "selfLink": false,
    "main": true,
    "module": true,
    "project": "./tsconfig.src.json",
    "exports": {
      "./package.json": "./package.json",
      ".": "./src/index.ts",
      "./extension": "./src/extension.ts"
    },
    "sourceDialects": [
      "@triggerdotdev/source"
    ]
  },
  "typesVersions": {
    "*": {
      "extension": [
        "dist/commonjs/extension.d.ts"
      ]
    }
  },
  "dependencies": {
    "@trigger.dev/core": "4.4.4",
    "tinyexec": "^0.3.2"
  },
  "devDependencies": {
    "@types/node": "20.14.14",
    "rimraf": "6.0.1",
    "tshy": "^3.0.2",
    "typescript": "^5.5.4",
    "tsx": "4.17.0",
    "esbuild": "^0.23.0",
    "@arethetypeswrong/cli": "^0.15.4",
    "@trigger.dev/build": "4.4.4",
    "@trigger.dev/sdk": "4.4.4"
  },
  "peerDependencies": {
    "@trigger.dev/sdk": "^4.4.4",
    "@trigger.dev/build": "^4.4.4"
  },
  "engines": {
    "node": ">=18.20.0"
  },
  "exports": {
    "./package.json": "./package.json",
    ".": {
      "import": {
        "@triggerdotdev/source": "./src/index.ts",
        "types": "./dist/esm/index.d.ts",
        "default": "./dist/esm/index.js"
      },
      "require": {
        "types": "./dist/commonjs/index.d.ts",
        "default": "./dist/commonjs/index.js"
      }
    },
    "./extension": {
      "import": {
        "@triggerdotdev/source": "./src/extension.ts",
        "types": "./dist/esm/extension.d.ts",
        "default": "./dist/esm/extension.js"
      },
      "require": {
        "types": "./dist/commonjs/extension.d.ts",
        "default": "./dist/commonjs/extension.js"
      }
    }
  },
  "main": "./dist/commonjs/index.js",
  "types": "./dist/commonjs/index.d.ts",
  "module": "./dist/esm/index.js",
  "scripts": {
    "clean": "rimraf dist",
    "build": "tshy && pnpm run update-version",
    "dev": "tshy --watch",
    "typecheck": "tsc --noEmit -p tsconfig.src.json",
    "update-version": "tsx ../../scripts/updateVersion.ts",
    "check-exports": "attw --pack ."
  }
}

import { AsyncIterableStream } from "@trigger.dev/core/v3";
import { Result, Options as XOptions } from "tinyexec";
export type PythonExecOptions = Partial<XOptions> & {
    env?: {
        [key: string]: string | undefined;
    };
};
export declare const python: {
    run(scriptArgs?: string[], options?: PythonExecOptions): Promise<Result>;
    runScript(scriptPath: string, scriptArgs?: string[], options?: PythonExecOptions): Promise<Result>;
    runInline(scriptContent: string, options?: PythonExecOptions): Promise<Result>;
    stream: {
        run(scriptArgs?: string[], options?: PythonExecOptions): AsyncIterableStream<string>;
        runScript(scriptPath: string, scriptArgs?: string[], options?: PythonExecOptions): AsyncIterableStream<string>;
        runInline(scriptContent: string, options?: PythonExecOptions): AsyncIterableStream<string>;
    };
};

import { defineConfig } from "@trigger.dev/sdk/v3";
import { pythonExtension } from "@trigger.dev/python/extension";

export default defineConfig({
  project: process.env.TRIGGER_PROJECT_REF!,
  dirs: ["./src/trigger"],
  maxDuration: 3600,
  build: {
    extensions: [
      pythonExtension({
        requirementsFile: "./requirements.txt",
        scripts: ["./scripts/**/*.py"],
      }),
    ],
  },
});
